    private void drawNode(Graphics g, BinaryNode&lt;Integer&gt; node, int x, int y, int offset) {
        g.setColor(Color.BLACK);
        if (node.left != null) {
            g.drawLine(x, y, x - offset, y + 60);
            drawNode(g, node.left, x - offset, y + 60, offset / 2);
        }
        if (node.right != null) {
            g.drawLine(x, y, x + offset, y + 60);
            drawNode(g, node.right, x + offset, y + 60, offset / 2);
        }

        g.setColor(new Color(173, 216, 230)); // color azul claro
